const body = $json.body ?? $json;

const memoryId = body.memory_id ?? body.entry_id ?? body.memory_entry_id ?? body.memory_entry?.id;
const childId = body.child_id ?? body.memory_entry?.child_id;
const transcription = body.transcription ?? body.transcript_text ?? body.memory_entry?.transcript_text;
const ownerId = body.owner_id ?? body.memory_entry?.owner_id ?? null;
const createdByUserId = body.created_by_user_id ?? body.memory_entry?.created_by_user_id ?? null;
const createdAt = body.created_at ?? body.event_created_at ?? new Date().toISOString();
const language = body.language ?? body.language_code ?? body.memory_entry?.language_code ?? 'en';

if (!memoryId) throw new Error('Missing required field: entry_id/memory_id');
if (!childId) throw new Error('Missing required field: child_id');
if (!transcription || !String(transcription).trim()) throw new Error('Missing required field: transcription');

return [{
  json: {
    memory_id: String(memoryId),
    child_id: String(childId),
    owner_id: ownerId ? String(ownerId) : null,
    created_by_user_id: createdByUserId ? String(createdByUserId) : null,
    transcription: String(transcription).trim(),
    event_created_at: String(createdAt),
    language_code: String(language),
    transcript_version: Number(body.transcript_version ?? 1),
    idempotency_key: String(body.idempotency_key ?? `${memoryId}:v${Number(body.transcript_version ?? 1)}`)
  }
}];

const categories = new Set(['milestone', 'funny', 'behavior', 'health', 'other']);
const emotions = new Set(['joy', 'neutral', 'sadness', 'surprise', 'anger', 'fear', 'other']);

const parseModelOutput = (value) => {
  if (value == null) return {};
  if (typeof value === 'object') return value;
  const text = String(value).trim();
  if (!text) return {};
  return JSON.parse(text);
};

const clampImportance = (value) => {
  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed)) return 1;
  return Math.max(1, Math.min(10, parsed));
};

const clampConfidence = (value) => {
  const parsed = Number.parseFloat(value);
  if (!Number.isFinite(parsed)) return 0;
  return Math.max(0, Math.min(1, parsed));
};

const normalizeArray = (value, maxItems) => {
  if (!Array.isArray(value)) return [];
  return value.map((v) => String(v ?? '').trim()).filter(Boolean).slice(0, maxItems);
};

let parsed;
const rawContent = $json.choices?.[0]?.message?.content ?? '';

try {
  parsed = parseModelOutput(rawContent);
} catch (error) {
  return [{
    json: {
      route: 'raw_save',
      enriched: false,
      enrichment_status: 'FAILED',
      params: {
        memory_id: $json.memory_id,
        owner_id: $json.owner_id,
        child_id: $json.child_id,
        created_by_user_id: $json.created_by_user_id,
        summary: 'Enrichment failed validation.',
        category: 'other',
        emotion: 'neutral',
        sentiment_score: null,
        keywords: [],
        tags: [],
        importance_score: 1,
        is_highlight: false,
        milestone_hint: null,
        embedding_id: null,
        model_name: $vars.OPENAI_MODEL || 'gpt-4o-mini',
        model_version: null,
        prompt_version: 'enrichment-v2',
        schema_version: '1.0.0',
        confidence_score: 0,
        model_cost_usd: null,
        raw_response: { raw_text: String(rawContent) },
        processed_at: new Date().toISOString(),
        run_status: 'FAILED'
      }
    }
  }];
}

const categoryCandidate = String(parsed.category ?? '').trim().toLowerCase();
const emotionCandidate = String(parsed.emotion ?? 'neutral').trim().toLowerCase();
const importanceScore = clampImportance(parsed.importance_score);
const confidenceScore = clampConfidence(parsed.confidence_score);
const normalizedCategory = categories.has(categoryCandidate) ? categoryCandidate : 'other';
const normalizedEmotion = emotions.has(emotionCandidate) ? emotionCandidate : 'neutral';
const summary = String(parsed.summary ?? '').trim();
const schemaVersion = String(parsed.schema_version ?? '1.0.0').trim();
const processedAt = (() => {
  const date = new Date(parsed.processed_at ?? Date.now());
  return Number.isNaN(date.getTime()) ? new Date().toISOString() : date.toISOString();
})();
const keywords = normalizeArray(parsed.keywords, 6);
const tags = normalizeArray(parsed.tags, 20);
const sentimentScore = typeof parsed.sentiment_score === 'number' ? parsed.sentiment_score : null;
const modelCostUsd = parsed.model_cost_usd == null ? null : Number(parsed.model_cost_usd);
const modelName = String(parsed.model_name ?? ($vars.OPENAI_MODEL || 'gpt-4o-mini')).trim();
const modelVersion = parsed.model_version == null ? null : String(parsed.model_version).trim();
const promptVersion = String(parsed.prompt_version ?? 'enrichment-v2').trim();
const milestoneHint = parsed.milestone_hint == null ? null : String(parsed.milestone_hint).trim();
const embeddingId = parsed.embedding_id == null ? null : String(parsed.embedding_id).trim();
const isHighlight = typeof parsed.is_highlight === 'boolean'
  ? parsed.is_highlight
  : (importanceScore >= 8 || normalizedCategory === 'milestone');

const requiredErrors = [];
if (!summary) requiredErrors.push('summary is required');
if (!schemaVersion) requiredErrors.push('schema_version is required');
if (!Number.isFinite(confidenceScore)) requiredErrors.push('confidence_score is required');

if (requiredErrors.length > 0) {
  return [{
    json: {
      route: 'raw_save',
      enriched: false,
      enrichment_status: 'FAILED',
      errors: requiredErrors,
      params: {
        memory_id: $json.memory_id,
        owner_id: $json.owner_id,
        child_id: $json.child_id,
        created_by_user_id: $json.created_by_user_id,
        summary: 'Enrichment failed validation.',
        category: 'other',
        emotion: 'neutral',
        sentiment_score: null,
        keywords: [],
        tags: [],
        importance_score: 1,
        is_highlight: false,
        milestone_hint: null,
        embedding_id: null,
        model_name: modelName || 'gpt-4o-mini',
        model_version: modelVersion,
        prompt_version: promptVersion || 'enrichment-v2',
        schema_version: schemaVersion || '1.0.0',
        confidence_score: 0,
        model_cost_usd: null,
        raw_response: { parsed },
        processed_at: new Date().toISOString(),
        run_status: 'FAILED'
      }
    }
  }];
}

return [{
  json: {
    route: 'valid_upsert',
    enriched: true,
    enrichment_status: 'SUCCESS',
    params: {
      memory_id: $json.memory_id,
      owner_id: $json.owner_id,
      child_id: $json.child_id,
      created_by_user_id: $json.created_by_user_id,
      summary,
      category: normalizedCategory,
      emotion: normalizedEmotion,
      sentiment_score: sentimentScore,
      keywords,
      tags,
      importance_score: importanceScore,
      is_highlight: isHighlight,
      milestone_hint: milestoneHint || null,
      embedding_id: embeddingId || null,
      model_name: modelName || 'gpt-4o-mini',
      model_version: modelVersion,
      prompt_version: promptVersion || 'enrichment-v2',
      schema_version: schemaVersion || '1.0.0',
      confidence_score: confidenceScore,
      model_cost_usd: Number.isFinite(modelCostUsd) ? modelCostUsd : null,
      raw_response: parsed,
      processed_at: processedAt,
      run_status: 'SUCCESS'
    }
  }
}];
